"""Report all prespecified interventions and deterministic support certificates."""
import time
from common import *
def rows(p):return list(csv.DictReader(Path(p).open()))
def md(head,data):return '\n'.join(['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']+['| '+' | '.join(map(str,x))+' |' for x in data])
def main():
 assert read(R/'formal_complete.json')['points']==39 and read(R/'reviews/diagnostic_audit.json')['status'].startswith('PASS')
 t=time.perf_counter();points=[];pairs=[];covers=[];impacts=[];certs=[]
 for ds in ANCHORS:
  out=R/'analysis'/ds;pp=rows(out/'points.csv');cc=rows(out/'coverage.csv');points+=pp;pairs+=rows(out/'paired.csv');covers+=cc;impacts.append(read(out/'intervention.json'));base=next(x for x in pp if x['method']=='GT10' and x['L']=='200')
  for x in cc:
   point=next(z for z in pp if z['method']==x['method'] and z['L']=='200');up=int(base['hits'])+int(x['pool_covered']);scanup=int(base['hits'])+int(x['scan_covered']);control=[z for z in pp if z['method']=='GT10'];dom=[z for z in control if int(z['hits'])>=up and float(z['qps'])>=float(point['qps'])];scandom=[z for z in control if int(z['hits'])>=scanup and float(z['qps'])>=float(point['qps'])]
   certs.append(dict(dataset=ds,K=100,L=200,method=x['method'],n=base['n'],base_hits=base['hits'],actual_hits=point['hits'],pool_covered=x['pool_covered'],scan_covered=x['scan_covered'],optimistic_pool_hit_ceiling=up,optimistic_pool_recall_ceiling_pct=100*up/(int(base['n'])*100),optimistic_scan_hit_ceiling=scanup,current_complete_QPS=point['qps'],GT_dominating_even_pool_oracle_L=','.join(z['L'] for z in dom),GT_dominating_even_scan_oracle_L=','.join(z['L'] for z in scandom),scope='Excludes improvements confined to current candidate pool at current measured cost; not a future implementation speed lower bound.'))
 csvwrite(R/'analysis/all_native_points.csv',points);csvwrite(R/'analysis/all_native_paired.csv',pairs);csvwrite(R/'analysis/all_native_coverage.csv',covers);csvwrite(R/'analysis/oracle_cost_certificates.csv',certs);dump(R/'analysis/intervention_effects.json',impacts)
 bounds=rows(R/'analysis/support_bounds.csv');near=rows(R/'analysis/nearest_query_strata.csv');zero=rows(R/'analysis/zero_source_strata.csv');interpretation=read(R/'reviews/interpretation.json')
 lines=['# E192：相似查询不共享邻域，是否使补全无用？','2026-10-29。新做三集K100同窗口39点/117轮完整T1测量，36资格点另计；七集真实两K/L200旧实际包用于32固定重配诊断。未重跑整个E191；无新盲确认，默认E99 GT10保持。','## 直接结论']+interpretation['conclusions']
 lines+=['## 证明的精确范围','设主返回R、严格GT目标G、可追加候选C、最终返回F⊆R∪C，则\n\n`|G∩F|−|G∩R| ≤ |(G\\R)∩C|`。\n\n遗漏不在候选集合中，任何排序都不能产生正收益。固定ID表还有C⊆训练遗漏ID并集S，故平均ΔRecall≤Σ|(G\\R)∩S|/(nK)。[完整推导](theory.md)。','这没有把“邻域共享”重定义为候选覆盖后声称证明原判断：两者是不同命题。共享GT、共享遗漏ID、共享块与廉价候选支持分别测量，只有后者直接进入集合上界。共享非空也不保证费用划算。','## 七集实际候选支持上界：K100/L200',md(['数据','原遗漏','旧ID源内遗漏','固定ID理想Δpp','正常池覆盖','块池理想Δpp','打乱池32次均值[min,max]'],[[LABEL[x['dataset']],x['missing_members'],x['old_source_covered'],f"{float(x['fixed_ID_ceiling_pp']):.4f}",x['normal_pool_covered'],f"{float(x['block_pool_ceiling_pp']):.4f}",f"{float(x['permuted_pool_mean']):.1f} [{x['permuted_pool_min']},{x['permuted_pool_max']}]" ] for x in bounds if x['K']=='100']),'以上是支持集上界，不是免费可执行的排序器；未扣96容量、原metric并列/浮点或访问费用。固定ID表上界只约束原源S，不限制访问S外ID的块法。','## 同数据集、同窗口的表行重配','正常与SHUFFLE-SQ共用原base/metric/图/画像、实际主返回、所有块/码、SQ评分和严格合并。只将hub→完整训练块表行在同长度组内重配。全局表行/块频次和每hub行长度保持，主返回块保持；在线预定seed20261029，未挑重配。实际去重和扫描量可能变化，逐项报告。','三集正式真实K100；每点warm256、三轮方法轮转，CPU15实际1线程、各数值库1，完整Batch正常创建/初始化、路由、主搜、补全、六数组复制和销毁计时。保存、GT/oracle/hash在外。不能把下面新绝对QPS拼入E191旧计时窗口。']
 for ds in ANCHORS:
  pp=[x for x in points if x['dataset']==ds];pa={x['method']:x for x in pairs if x['dataset']==ds};ip=next(x for x in impacts if x['dataset']==ds)
  lines+=['### '+LABEL[ds],md(['方法 L200','Recall%','完整QPS','ΔRecall pp','完整耗时增幅%','扫码/q','追加精算/q','成员救回/损伤'],[[x['method'],f"{float(x['recall_pct']):.4f}",f"{float(x['qps']):.2f}",f"{float(pa[x['method']]['recall_delta_pp']):+.4f}" if x['method']!='GT10' else '—',f"{float(pa[x['method']]['extra_time_pct']):+.2f}" if x['method']!='GT10' else '—',f"{float(x['scanned_codes_per_query']):.1f}" if x['method'] not in ['GT10','B32'] else '—',f"{float(x['exact_scores_per_query']):.1f}" if x['method'] not in ['GT10','B32'] else '—',f"{pa[x['method']]['members_rescued']}/{pa[x['method']]['members_damaged']}" if x['method']!='GT10' else '—'] for x in pp if x['L']=='200']),f"正常SQ减打乱SQ：{ip['normal_minus_shuffled_hits']:+d}个GT100成员、{ip['normal_minus_shuffled_recall_pp']:+.4f}pp；正常更好/打乱更好/相同query={ip['normal_better_queries']}/{ip['shuffle_better_queries']}/{ip['equal_queries']}。",md(['方法','池覆盖','扫描覆盖','96短名单覆盖','最终救回'],[[x['method'],x['pool_covered'],x['scan_covered'],x['shortlist_covered'],x['rescued_members']] for x in covers if x['dataset']==ds]),md(['方法','达到其Recall的GT10 L','阈值速度差%','同时覆盖Recall/QPS的GT10 L'],[[x['method'],x['target_GT_L'],f"{float(x['target_speed_delta_pct']):+.2f}" if x['target_speed_delta_pct'] else '未覆盖',x['dominated_by_GT_L'] or '当前网格无'] for x in pairs if x['dataset']==ds])]
 lines+=['## 即使当前候选池全部完美救回，当前费用是否仍被覆盖？',md(['数据','方法','实际命中','池内理想命中上限','理想Recall%','当前完整QPS','覆盖池oracle的GT10 L'],[[LABEL[x['dataset']],x['method'],x['actual_hits'],x['optimistic_pool_hit_ceiling'],f"{float(x['optimistic_pool_recall_ceiling_pct']):.4f}",f"{float(x['current_complete_QPS']):.2f}",x['GT_dominating_even_pool_oracle_L'] or '当前网格未证实'] for x in certs]),'证书用整数GT命中数判断，不从浮点Recall四舍五入推门。池上限已乐观到忽略原扫描/96筛选损失；若GT10仍以更高/同Recall和QPS覆盖，则仅在当前池内改善排序、维持当前完整费用，不能超出该控制。未来更快实现或新候选源不受此费用结论约束。','## 最近训练query的零共享分层',md(['数据','方法','最近GT100重合为0的q','其原遗漏','实际救回','损伤','改善q'],[[LABEL[x['dataset']],x['method'],x['queries'],x['missing_members'],x['rescued_members'],x['damaged_members'],x['improved_queries']] for x in near if x['K']=='100' and x['stratum']=='nearest_GT_zero']),'原E185每集512条固定query，按原ID与E191实际返回对齐。这里的“最近”对L2为原查询平方L2；IP为单位query余弦的旧诊断，原检索仍raw IP。零重合只针对选定最近训练query，不代表整个16K或所有近query都无共享。GT100分层对两K共用，K1表不改称GT1共享标签。完整最近遗漏=0/正分层见CSV，不提供分层线上QPS。','## 整个旧残差ID源完全不覆盖本次遗漏的查询',md(['数据','方法','无旧源覆盖q','原遗漏成员','实际救回','损伤','改善q'],[[LABEL[x['dataset']],x['method'],x['queries'],x['missing_members'],x['rescued_members'],x['damaged_members'],x['improved_queries']] for x in zero if x['K']=='100']),'这些实际返回直接反驳“与旧残差源无共同遗漏ID，则所有块法质量增量为零”的说法；不反驳固定ID源定理，也不证明线上划算。可核具体query/GT/主返回/救回ID：[实际反例](analysis/actual_counterexamples.json)。','## 数学反例与普遍命题','库X={0,2}，训练query=1−ε、测试query=1+ε，GT1不相交而query可任意接近。训练遗漏ID0所在块包含两ID，测试主返回ID0时，扫描该块可救回ID1；ID1不在训练遗漏源。这证明目标ID共享不是所有块法的必要条件。[可执行反例](analysis/mathematical_counterexample.json)。这是集合模型反例，不冒充本地ANN性能。','## 核验、费用及限制','36资格点中原五方法的实际返回与E191对应包前缀逐字节一致；正式三轮包SHA、全量原生补全oracle、逐query2048/96上限和PQ/SQ扫描一致性通过。另份stdlib脚本复算全部新质量/救损/覆盖及同窗口GT10覆盖；七集32重配的全部query池覆盖由stdlib集合独立重算。同一执行者不同实现，不称独立人员或新盲确认。','随机重配干预的是hub表对应关系，不是数据几何，也不是让全部候选独立于query；主返回块和原metric块排序仍携带query信息。32次重配只描述池覆盖分布，不当成32个独立测试集。不同数据集metric/维数/规模/训练密度未配平，不能把跨集差异全归因共享。','各阶段suite费用、峰RSS与实际线程见reviews/*.receipt.json；查询QPS之外的资格、构建、诊断与核验另计，旧图/教师/码本构建债未清零。共同benchmark RSS不等于独立部署增量。原metric追加精算、块中心、SQ/PQ码次数分别报告，没有分段时间或总NDC归因。','当前根文档按新任务更新；E191 seal中的旧根文档原字节在本轮source_before，迁移收据不改旧seal。E191原PDF/科学文件保持，新增大产物在/root/acsg-e192-storage。','## 复核入口','[协议](protocol.md) · [理论](theory.md) · [冻结](freeze.json) · [全部新计时点](analysis/all_native_points.csv) · [新救损/控制](analysis/all_native_paired.csv) · [新覆盖](analysis/all_native_coverage.csv) · [上界证书](analysis/oracle_cost_certificates.csv) · [七集支持上界](analysis/support_bounds.csv) · [32重配](analysis/permutation_pool.csv) · [最近query分层](analysis/nearest_query_strata.csv) · [全部诊断复核](reviews/diagnostic_audit.json)']
 (R/'report_zh.md').write_text('\n\n'.join(lines)+'\n')
 dump(R/'reviews/report_build.json',dict(status='PASS_E192_PROOF_AND_CONTROL_REPORT',formal_points=len(points),formal_batches=3*len(points),oracle_certificates=len(certs),normal_SQ_pool_oracle_covered=[x['dataset'] for x in certs if x['method']=='REUSE-SQ' and x['GT_dominating_even_pool_oracle_L']],default_changed=False,seconds=time.perf_counter()-t));print('PASS E192 report and support certificates built',flush=True)
if __name__=='__main__':main()
